import{_ as o,o as i,c as t,ak as a}from"./chunks/framework.C5PBIMEM.js";const _=JSON.parse('{"title":"Godot 4 入门教程｜零基础游戏开发学习指南","description":"本教程带你从零开始学习 Godot 4 游戏开发，包括安装、基础操作与学习路线，适合新手和独立开发者快速入门。","frontmatter":{"title":"Godot 4 入门教程｜零基础游戏开发学习指南","description":"本教程带你从零开始学习 Godot 4 游戏开发，包括安装、基础操作与学习路线，适合新手和独立开发者快速入门。"},"headers":[],"relativePath":"godot/index.md","filePath":"godot/index.md","lastUpdated":1780925516000}'),e={name:"godot/index.md"};function d(r,l,p,n,s,c){return i(),t("div",null,[...l[0]||(l[0]=[a('<h1 id="godot-4-入门教程-零基础游戏开发指南" tabindex="-1">Godot 4 入门教程｜零基础游戏开发指南 <a class="header-anchor" href="#godot-4-入门教程-零基础游戏开发指南" aria-label="Permalink to “Godot 4 入门教程｜零基础游戏开发指南”">​</a></h1><p>欢迎来到 Godot 4 入门教程。</p><p>本教程将帮助你从零开始学习 Godot 4 游戏开发，逐步掌握 2D 游戏制作基础，并最终能够独立完成自己的小游戏项目。</p><p>无论你是：</p><ul><li>完全没有游戏开发经验的新手</li><li>想从 Unity 转向 Godot 的开发者</li><li>想学习 2D 游戏制作的人</li><li>想开发独立游戏的创作者</li></ul><p>都可以从这里开始学习。</p><h2 id="什么是-godot-4" tabindex="-1">什么是 Godot 4？ <a class="header-anchor" href="#什么是-godot-4" aria-label="Permalink to “什么是 Godot 4？”">​</a></h2><p>Godot 4 是一款免费、开源的游戏引擎，用于制作 2D 和 3D 游戏。</p><p>它的特点是：</p><ul><li>完全免费，没有商业授权费用</li><li>轻量级，运行速度快</li><li>非常适合独立游戏开发</li><li>学习成本低（相比 Unity 更简单）</li></ul><h2 id="godot-4-新手学习路线" tabindex="-1">Godot 4 新手学习路线 <a class="header-anchor" href="#godot-4-新手学习路线" aria-label="Permalink to “Godot 4 新手学习路线”">​</a></h2><p>如果你是新手，建议按照以下顺序学习：</p><ol><li>安装 Godot 4</li><li>熟悉编辑器界面</li><li>学习节点（Node）和场景（Scene）</li><li>制作角色移动系统</li><li>学习碰撞检测</li><li>添加动画系统</li><li>制作第一个完整小游戏</li></ol><h2 id="学习建议-非常重要" tabindex="-1">学习建议（非常重要） <a class="header-anchor" href="#学习建议-非常重要" aria-label="Permalink to “学习建议（非常重要）”">​</a></h2><p>很多人学习游戏开发时容易陷入：</p><ul><li>收藏教程</li><li>看教程</li><li>换教程</li></ul><p>但没有真正做出项目。</p><p>正确方式是：</p><p>👉 学一个功能 → 立刻做一个小Demo</p><p>例如：</p><ul><li>学移动 → 做一个可以控制的角色</li><li>学碰撞 → 做墙体阻挡玩家</li><li>学动画 → 做角色跑步动画</li></ul><p>这样学习效率会高很多。</p>',22)])])}const G=o(e,[["render",d]]);export{_ as __pageData,G as default};
